//
// POSIX equivalent of os/oseventtrace.cxx.  Upstream wraps the
// autogenerated MOF/ETW provider; on Linux this layer is the dispatch
// point for the optional LTTng UST provider that lives in
// libese_tracepoints.so.
//
// Loading model: the engine's libese.so does NOT hard-link lttng-ust.
// At first use we `dlopen("libese_tracepoints.so", RTLD_LAZY)` and
// look up a single C-linkage symbol — `EseTracepointGetTable` — which
// returns a struct of function pointers (one per tracepoint).  If
// either the .so or the symbol is missing, the table pointer stays
// null and every dispatch is a quiet no-op.  Boxes without lttng-ust
// installed therefore see no behaviour change.
//
// All four files driving this — the table header, the .so trampoline
// source, the LTTng TRACEPOINT_EVENT defs, and the OSEventTrace_
// dispatch body — are emitted by `tools/etwlttng` from
// `EseEtwEventsPregen.txt`.  Regeneration is wired through the
// `gen_etwlttng` CMake target.

#include "osstd.hxx"

#include "ese_tracepoint_table.h"

#include <dlfcn.h>
#include <pthread.h>
#include <stdint.h>
#include <stdio.h>


namespace
{


//  -------- loader state --------

const EseTracepointTable * g_pTracepointTable = nullptr;
void *                     g_phTracepointsSo  = nullptr;
pthread_once_t             g_onceInit         = PTHREAD_ONCE_INIT;


void TracepointsInitOnce()
{
    //  RTLD_LOCAL keeps lttng-ust symbols out of the global namespace
    //  so a host process embedding ESE doesn't accidentally satisfy
    //  its own lttng-ust references against ours.
    g_phTracepointsSo = dlopen( "libese_tracepoints.so", RTLD_LAZY | RTLD_LOCAL );
    if ( g_phTracepointsSo == nullptr )
    {
        return;
    }

    auto pfnGetTable = reinterpret_cast<EseTracepointGetTableFn>(
        dlsym( g_phTracepointsSo, "EseTracepointGetTable" ) );
    if ( pfnGetTable == nullptr )
    {
        return;
    }

    const EseTracepointTable * pTable = pfnGetTable();
    if ( pTable == nullptr || pTable->version != ESE_TRACEPOINT_TABLE_VERSION )
    {
        return;
    }

    g_pTracepointTable = pTable;
}


void TracepointsEnsureInit()
{
    pthread_once( &g_onceInit, TracepointsInitOnce );
}


//  -------- helpers for the generated dispatch --------

//  Convert a 16-bit-WCHAR NUL-terminated string into UTF-8 in a
//  caller-supplied buffer.  The dispatch generator calls this for
//  every win:UnicodeString field so the trampoline can take char*
//  (which lttng-ust's ctf_string consumes).
void EseTpDispatchWideToUtf8( const uint16_t * wsz, char * utf8, size_t cbUtf8 )
{
    if ( cbUtf8 == 0 )
    {
        return;
    }
    if ( wsz == nullptr )
    {
        utf8[ 0 ] = '\0';
        return;
    }
    const int cb = WideCharToMultiByte( CP_UTF8, 0,
                                        reinterpret_cast<const WCHAR*>( wsz ), -1,
                                        utf8, (int)cbUtf8,
                                        nullptr, nullptr );
    if ( cb <= 0 )
    {
        utf8[ 0 ] = '\0';
    }
}


#include "oseventtrace_dispatch.g.cxx"

} // anonymous namespace


////////////////////////////////////////////////
//  Lifecycle

void OSEventTracePostterm()
{
}

BOOL FOSEventTracePreinit()
{
    TracepointsEnsureInit();
    return fTrue;
}

void OSEventTraceTerm()
{
}

ERR ErrOSEventTraceInit()
{
    TracepointsEnsureInit();
    return JET_errSuccess;
}


////////////////////////////////////////////////
//  Trace recording — generated dispatch

void __cdecl OSEventTrace_( const ULONG etguid, const size_t cData, ... )
{
    const EseTracepointTable * pTable = g_pTracepointTable;
    if ( pTable == nullptr )
    {
        return;
    }
    (void)cData;

    va_list ap;
    va_start( ap, cData );

    EseTpDispatch( etguid, ap, pTable );

    va_end( ap );
}


////////////////////////////////////////////////
//  Compile-time / runtime trace gates
//
//  The non-templated FOSEventTraceEnabled() (in oseventtrace.hxx)
//  returns fTrue so OSEventTrace_ runs and our dispatch sees the
//  etguid.  The templated FOSEventTraceEnabled<etguid>() stays
//  fFalse for now — that gate is only consulted by a handful of
//  call sites that do expensive data-gathering before the trace
//  call.  Flipping those to query lttng's per-tracepoint enable
//  state is follow-up work.

template BOOL FOSEventTraceEnabled<_etguidCacheRequestPage>();

template BOOL FOSEventTraceEnabled<_etguidCacheMemoryUsage>();

template BOOL FOSEventTraceEnabled<_etguidInstStationId>();

template BOOL FOSEventTraceEnabled<_etguidDiskStationId>();

template BOOL FOSEventTraceEnabled<_etguidFileStationId>();

template BOOL FOSEventTraceEnabled<_etguidSysStationId>();

template BOOL FOSEventTraceEnabled<_etguidIsamDbfilehdrInfo>();

template BOOL FOSEventTraceEnabled<_etguidFmpStationId>();

template BOOL COSEventTraceIdCheck::FAnnounceTime<_etguidInstStationId>(const TraceStationIdentificationReason);

template BOOL COSEventTraceIdCheck::FAnnounceTime<_etguidDiskStationId>(const TraceStationIdentificationReason);

template BOOL COSEventTraceIdCheck::FAnnounceTime<_etguidFileStationId>(const TraceStationIdentificationReason);

template BOOL COSEventTraceIdCheck::FAnnounceTime<_etguidSysStationId>(const TraceStationIdentificationReason);

template BOOL COSEventTraceIdCheck::FAnnounceTime<_etguidIsamDbfilehdrInfo>(const TraceStationIdentificationReason);

template BOOL COSEventTraceIdCheck::FAnnounceTime<_etguidFmpStationId>(const TraceStationIdentificationReason);
